        "Et gehéiert zu de Wiesselpräpositiounen: op d'Fro Wo? (wou?) follegt den Dativ (an der Tür), op d'Fro Wohin? (wouhin?) den Akkusativ (an die Tür). Zesummegezunn: an dem → am, an das → ans.",
