        "D'Präpositioun verlaangt den Dativ: ab nächstem Monat, ab dem 1. Mai. Virun Deeg steet se dacks ouni Artikel: ab Montag, ab morgen. Ab ass och e trennbare Präfix: abfahren (fortfueren), abholen (ofhuelen, sichen).",
