        "Der kënnt och an anere Fäll vir: beim Femininum am Dativ a Genitiv (der Frau), a fir all Geschlechter am Genitiv Pluriel (die Autos der Eltern). Beim Maskulinum ass den Akkusativ den, den Dativ dem, de Genitiv des.",
        "Op Lëtzebuergesch ass de männlechen Artikel de oder den (n-Regel), an e mécht keen Ënnerscheed tëscht Nominativ an Akkusativ; op Däitsch muss een der an den auserneenhalen. Léier d'Geschlecht mam Wuert."
