        "Am Singular: das Eis. De Pluriel ass seelen; beim Bestellen seet een zwei Eis (zwou Glacen). De Kontext weist, wat gemengt ass. Op Lëtzebuergesch huet een zwee Wierder, Äis a Glace; op Däitsch heescht béides Eis.",
