        "Haaptiddi: geben heescht engem eppes ginn. Typesch Struktur: jemandem (Dativ, wiem?) etwas (Akkusativ, wat?): Ich gebe dir das Buch.",
        "Formen: du gibst, er gibt (e → i), gab, hat gegeben. Den Ausdrock es gibt + Akkusativ heescht 'et gëtt, et ass do': Es gibt hier ein Café — grad wéi op Lëtzebuergesch.",
