        "Ee Brudder oder eng Schwëster heescht der Bruder oder die Schwester. Den Artikel ass die Geschwister, an d'Verb steet am Pluriel: Meine Geschwister wohnen in Hamburg. Am Dativ: mit meinen Geschwistern.",
