        "Formen: kennt, kannte, hat gekannt. Ëmmer mam Akkusativ: jemanden/etwas kennen. An der Vergaangenheet ännert de Vokal: kennen → kannte (mat a).",
        "Ënnerscheed zu wissen: kennen — e Mënsch oder eng Plaz kennen, wissen — e Fakt wëssen: Ich kenne ihn, mee Ich weiß, dass er Arzt ist. Op Lëtzebuergesch ass et genee esou: kennen ↔ wëssen."
