        "Plural: die Länder (Staaten); historesch och die Lande, mee dat ass rar. Ausdréck: aufs Land fahren (op d'Land fueren), auf dem Land leben (um Land wunnen), im Ausland / im Inland.",
        "An Däitschland ass das Bundesland e Bundesland, also en Deelstaat. Buedem oder Grond heescht der Boden, net das Land."
