        "Komparativ: länger (méi laang), Superlativ: am längsten. D'Adverb lange heescht „laang“ am Sënn vu „vill Zäit“: Ich warte schon lange. Mat Endung: eine lange Reise, lange Haare.",
        "Fro: Wie lange dauert es? (Wéi laang dauert et?) — do steet lange, net lang."
