        "Formen: ich lasse, du lässt, er lässt; Präteritum ließ, Perfekt hat gelassen. Mat engem Infinitiv ass de Perfekt hat lassen (net gelassen): Er hat mich gehen lassen. Imperativ: Lass! / Lasst uns! (loosst eis…).",
        "Mam Akkusativ: etwas lassen; mat Infinitiv (ouni zu): jemanden etwas tun lassen. Dacks: Lass mich in Ruhe! — Looss mech a Rou!"
