        "Ausdréck: keinen Laut von sich geben (kee Mucks maachen), ein Laut der Überraschung (en Iwwerraschungsruff). An der Sproochwëssenschaft: Vokale und Konsonanten sind Laute.",
        "Ënnerscheed zu laut: laut ass en Adjektiv „haart“; Laut — Substantiv „Toun“. En Toun an der Musek an e Kaméidi heeschen Ton a Geräusch."
