        "Heefeg Verbindungen: morgen früh (muer de Moien), morgen Abend (muer den Owend), bis morgen (bis muer), übermorgen (iwwermuer). D'Dagzäit no morgen gëtt grouss geschriwwen: morgen Nachmittag.",
