        "Formen: schwimmt, schwamm, ist geschwommen (staarkt Verb). Mat Richtung steet am Perfekt ist: Sie ist über den See geschwommen; och fir d'Aktivitéit benotzt d'Standardsprooch dacks ist (Ich bin gestern geschwommen), heiansdo hat.",
        "Nieft schwimmen gëtt et op Däitsch och baden: Wann ee sech am Mier oder am Séi erfrëscht, seet een dacks baden: Wir baden im Meer. Op Lëtzebuergesch seet een och „schwammen“ oder „bueden“."
