        "Normalerweis kënnt en Objet am Akkusativ: Ich sehe einen Hund. Reflexiv heescht sich sehen sech treffen oder sech géigesäiteg gesinn: Wir sehen uns morgen.",
        "Wann een bewosst, méi laang oder op eppes Bestëmmtes kuckt, benotzt een normalerweis schauen oder ansehen; sehen dréckt éischter d'Gesinn u sech aus."
