        "Fir déi aner Persoune ginn et aner Formen: ich – mich, du – dich, wir – uns, ihr – euch. Zum Beispill: er wäscht sich (hie wäscht sech), mee ich wasche mich.",
        "Vill däitsch Verbe si reflexiv (sich freuen, sich setzen, sich vorstellen), an op Lëtzebuergesch sinn et dacks och reflexiv Verben: sech freeën, sech setzen."
